def final_transform(grid):
    h,w=len(grid),len(grid[0])
    vals={v for row in grid for v in row}
    bg=max(vals,key=lambda v:sum(row.count(v) for row in grid))
    mark=next(v for v in vals if v!=bg)
    out=[row[:] for row in grid]
    # Bridge short interruptions in the dominant horizontal and vertical strokes.
    for r in range(h):
        inds=[c for c in range(w) if grid[r][c]==mark]
        if len(inds)>=4:
            for a,b in zip(inds,inds[1:]):
                if 1<=b-a-1<=2:
                    for c in range(a+1,b):
                        if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        inds=[r for r in range(h) if grid[r][c]==mark]
        if len(inds)>=4:
            for a,b in zip(inds,inds[1:]):
                if 1<=b-a-1<=2:
                    for r in range(a+1,b):
                        if grid[r][c]==bg: out[r][c]=2
    # A missing corner pixel on the boundary is marked when both incident sides continue the stroke.
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg or not (r==0 or r==h-1 or c==0 or c==w-1):
                continue
            adjacent=sum(0<=rr<h and 0<=cc<w and grid[rr][cc]==mark for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)))
            if adjacent>=2: out[r][c]=2
    return out
